from pathlib import Path
root=Path('work/sites/moon-and-pillow')
p=root/'app/page.tsx'
s=p.read_text(encoding='utf-8-sig')
def replace(old,new):
 global s
 if old not in s: raise RuntimeError('Missing replacement: '+old[:100])
 s=s.replace(old,new)
def line(prefix,new):
 global s
 matching=[v for v in s.splitlines() if v.strip().startswith(prefix)]
 if len(matching)!=1: raise RuntimeError('Line ambiguity: '+prefix)
 s=s.replace(matching[0],new)

replace('colors, productColors, colorName, money, products, resolveItem,','categories, categoryLabel, roomFor, firstColor, productImage, startingPrice, priceLabel, productColors, colorName, money, products, resolveItem,')
line('const catalog =',"const catalog = products.filter(product=>Boolean(productImage(product)));\nconst fold = (value:string)=>value.normalize('NFD').replace(/[\\u0300-\\u036f]/g,'').toLocaleLowerCase('fr');")
start=s.index('const faq = [')
end=s.index('\nfunction Sheet',start)
s=s[:start]+'''const faq = [
 ['Comment choisir ma taille ?', 'Chaque fiche présente les formats effectivement relevés chez le fournisseur. Vérifiez les dimensions en centimètres de votre couette, de votre oreiller ou de votre coussin. Les mentions King et Queen ne remplacent pas une mesure.'],
 ['Que contient chaque produit ?', 'Le contenu figure dans les détails de la fiche. Une housse peut être vendue sans garnissage. Les objets utilisés pour la mise en scène d’une photo ne sont pas nécessairement inclus.'],
 ['Les couleurs sont-elles identiques d’un produit à l’autre ?', 'Chaque référence possède son propre nuancier. Le vert clair des housses initiales et le vert olive du plaid sont différents. Les photographies fournisseurs ne prouvent pas que deux matières ont exactement la même teinte.'],
 ['Quand pourrai-je commander ?', 'La collection est en préparation. Les nouvelles références attendent la validation du coût livré, des variantes et de la livraison à l’unité avant l’ouverture des commandes.'],
 ['Quels seront les délais et les retours ?', 'Les délais, frais de livraison et conditions de retour seront précisés sur chaque fiche avant ouverture. Ils ne sont pas encore confirmés pour cette sélection.'],
];''' +s[end:]
replace("?initialColor:'blanc';","?initialColor:initialProduct?firstColor(initialProduct):'';")
replace("initialProduct?.options[0].id","initialProduct?.options[0]?.id")
replace("const [filter,setFilter]=useState<Category|'tout'>('tout'),","const [room,setRoom]=useState<'tout'|'chambre'|'salon'|'bain'>('tout');\n const [filter,setFilter]=useState<Category|'tout'>('tout'),")
line('const visible=', ''' const visible=catalog.filter(product=>(room==='tout'||roomFor(product)===room)&&(filter==='tout'||product.category===filter)&&fold(`${product.name} ${product.subtitle} ${productColors(product).map(c=>c.name).join(' ')}`).includes(fold(search))).sort((a,b)=>{
  const x=startingPrice(a),y=startingPrice(b); if(sort==='selection')return 0;if(!x&&!y)return 0;if(!x)return 1;if(!y)return -1;return sort==='prix-asc'?x-y:y-x;
 });
 const visibleCategories=categories.filter(category=>catalog.some(product=>product.category===category.id&&(room==='tout'||roomFor(product)===room)));''')
line('function openProduct('," function openProduct(product:Product,color:Color=firstColor(product)){if(color&&!product.availableColors.includes(color))return;setView({product,color});setOptionId(product.options[0]?.id??'');setQuantity(1);setDetailImage(null);}")
replace("function addItem(product:Product,color:Color,option:string,amount=1){const existing", "function addItem(product:Product,color:Color,option:string,amount=1){try{resolveItem({productId:product.id,color,optionId:option,quantity:amount});}catch{setNotice('Cette référence est encore en préparation.');return;}const existing")
replace("function chooseCategory(category:Category|'tout'){setFilter(category);", "function chooseCategory(category:Category|'tout'){setRoom('tout');setFilter(category);")
replace('const selectedOption=view?.product.options.find(o=>o.id===optionId);',"const selectedOption=view?.product.options.find(o=>o.id===optionId);\n const chooseRoom=(value:'tout'|'chambre'|'salon'|'bain')=>{setRoom(value);setFilter('tout');setMobileOpen(false);document.getElementById('collection')?.scrollIntoView({behavior:'smooth'});};")
line('<header className="site-header">', ''' <header className="site-header"><div className="header-inner">
 <button className="icon-button mobile-menu" aria-label="Ouvrir le menu" aria-expanded={mobileOpen} onClick={()=>setMobileOpen(!mobileOpen)}><Menu/></button>
 <a href="/" className="wordmark" aria-label="Moon and Pillow, accueil">Moon <i>&</i> Pillow<span>LES PETITS BONHEURS DE LA MAISON</span></a>
 <nav aria-label="Navigation principale"><a href="#collection" onClick={()=>{setRoom('tout');setFilter('tout');}}>La collection</a><a href="#collection" onClick={()=>{setRoom('chambre');setFilter('tout');}}>La chambre</a><a href="#collection" onClick={()=>{setRoom('salon');setFilter('tout');}}>Le salon</a><a href="#notre-univers">Notre univers</a></nav>
 <div className="header-actions"><button className="icon-button" aria-label="Rechercher un produit" onClick={()=>setSearchOpen(true)}><Search size={20}/></button><button className="icon-button bag-button" aria-label={`Ouvrir le panier, ${count} article${count>1?'s':''}`} onClick={()=>setCartOpen(true)}><ShoppingBag size={20}/>{count>0&&<span className="bag-count">{count}</span>}</button></div>
 </div>{mobileOpen&&<nav className="mobile-nav" aria-label="Menu mobile"><button onClick={()=>chooseRoom('tout')}>Toute la collection</button><button onClick={()=>chooseRoom('chambre')}>La chambre</button><button onClick={()=>chooseRoom('salon')}>Le salon</button><a href="#notre-univers" onClick={()=>setMobileOpen(false)}>Notre univers</a></nav>}</header>''')
line('<main id="main"><section className="hero">', ''' <main id="main"><section className="hero"><div className="hero-copy"><p className="eyebrow">L’ART DE SE SENTIR CHEZ SOI</p><h1>La douceur,<br/><em>à demeure.</em></h1><p className="hero-description">Des textures qu’on aime retrouver.<br/>Du canapé aux derniers instants du soir.</p><a className="button primary" href="#collection">Découvrir la collection <ArrowRight size={17}/></a></div><div className="hero-photo"><img src="/img/plaid-detente.jpg" alt="Un moment de détente sous un plaid blanc côtelé" fetchPriority="high"/></div></section>''')
line('<section className="intro-line"','')
line('<section id="collection"', ''' <section id="collection" className="collection section-wrap"><div className="section-top"><div><p className="eyebrow">LA COLLECTION EN PRÉPARATION</p><h2>Faire place <em>au confort.</em></h2></div><p>Des pièces pour la chambre et le salon.<br/>À explorer, une matière après l’autre.</p></div>
 <div className="room-nav" role="group" aria-label="Choisir une pièce">{([['tout','Tout découvrir'],['chambre','La chambre'],['salon','Le salon']]as const).map(([value,label])=><button key={value} aria-pressed={room===value} onClick={()=>{setRoom(value);setFilter('tout');}}>{label}</button>)}</div>
 <div className="catalog-toolbar"><label className="category-filter"><span className="sr-only">Filtrer par catégorie</span><select aria-label="Catégorie" value={filter} onChange={e=>setFilter(e.target.value as Category|'tout')}><option value="tout">Toutes les catégories</option>{visibleCategories.map(c=><option key={c.id} value={c.id}>{c.label}</option>)}</select></label><span className="collection-count" aria-live="polite">{visible.length} modèle{visible.length>1?'s':''}</span><label className="sort"><span className="sr-only">Trier les produits</span><select value={sort} onChange={e=>setSort(e.target.value)}><option value="selection">Notre sélection</option><option value="prix-asc">Prix croissant</option><option value="prix-desc">Prix décroissant</option></select><ChevronDown size={13}/></label></div>
 {search&&<div className="search-result">Résultats pour « {search} » <button onClick={()=>setSearch('')}>Effacer <X size={14}/></button></div>}''')
line('<div className="product-grid">', ''' <div className="product-grid">{visible.map(product=><article className="product-card" key={product.id}>
 <button className="product-image" onClick={()=>openProduct(product)} aria-label={`Découvrir ${product.name}`}><img src={productImage(product)} alt={product.name} loading="lazy"/><span className="discover">Découvrir <ArrowUpRight size={16}/></span></button>
 <div className="product-info"><div className="card-text"><button className="text-link product-title" onClick={()=>openProduct(product)}>{product.name}</button><p>{categoryLabel(product.category)}</p></div><span className="product-price">{!product.draftOnly&&product.options.length>1&&<small>Dès </small>}{priceLabel(product)}</span></div>
 <div className="card-bottom">{product.draftOnly?<span className="product-status">En préparation{product.availableColors.length>0?` · ${product.availableColors.length} coloris relevé${product.availableColors.length>1?'s':''}`:''}</span>:<div className="swatches" aria-label="Couleurs proposées">{productColors(product).map(c=><button key={c.id} title={c.name} aria-label={`${product.name} en ${c.name}`} onClick={()=>openProduct(product,c.id)} style={{'--swatch':c.hex}as CSSProperties}/>)}</div>}<button className="quick-add" aria-label={`Choisir ${product.name}`} onClick={()=>openProduct(product)}><Plus size={16}/></button></div>
 </article>)}</div>
 {visible.length===0&&<div className="empty-results"><Search size={28}/><h3>La douceur se fait attendre.</h3><p>Essayez une autre catégorie ou un autre mot.</p><button className="button secondary" onClick={()=>{setSearch('');setFilter('tout');setRoom('tout');}}>Revoir la collection</button></div>}
 <p className="catalog-note">Préouverture · Les prix de la sélection initiale sont indicatifs. Les nouvelles références attendent la validation des variantes et de leur coût livré.</p><a className="preparation-link" href="/catalogue-preparation">Voir les 25 références du catalogue de préparation <ArrowUpRight size={16}/></a></section>''')
replace('<span className="image-label">Les petits bonheurs sont ici.</span>','')
replace('LA COLLECTION CÔTELÉE','LA SÉLECTION MOON & PILLOW')
replace("placeholder=\"Un plaid rose, des housses…\"","placeholder=\"Une parure, un plaid, une couleur…\"")
replace('À explorer : blanc, rose, vert clair, vert olive.','Explorez les parures, taies, oreillers, housses et plaids de l’aperçu.')
line('{view&&<Sheet', ''' {view&&<Sheet title="Dans le détail" wide onClose={closeView}><div className="product-detail"><div className="detail-gallery">
 {productImage(view.product,view.color)?<img className="detail-main" src={detailImage??productImage(view.product,view.color)} alt={view.product.name}/>:<div className="detail-placeholder">Photographie en cours de sélection</div>}
 <div className="thumbnails">{[productImage(view.product,view.color),...view.product.gallery].filter((src):src is string=>Boolean(src)).map((src,index)=><button key={`${src}-${index}`} onClick={()=>setDetailImage(src)} aria-label={`Voir la photo ${index+1}`} aria-pressed={(detailImage??productImage(view.product,view.color))===src}><img src={src} alt=""/></button>)}</div>
 {view.product.photoNote&&<p className="source-note">{view.product.photoNote}</p>}</div>
 <div className="detail-copy"><p className="eyebrow">{categoryLabel(view.product.category)}</p><h2>{view.product.name}</h2><p className="detail-price">{priceLabel(view.product,optionId)}</p><p>{view.product.description}</p>
 <fieldset className="option-field"><legend>Couleur · <strong>{colorName(view.color,view.product)}</strong></legend>{productColors(view.product).length>0?<div className="color-options">{productColors(view.product).map(color=><button key={color.id} aria-label={color.name} aria-pressed={view.color===color.id} className={view.color===color.id?'chosen':''} onClick={()=>{setView({...view,color:color.id});setDetailImage(null);}}>{color.hex&&<span style={{background:color.hex}}/>}{color.name}</button>)}</div>:<p className="source-note">Le nuancier exact reste à confirmer.</p>}</fieldset>
 <fieldset className="option-field"><legend>Format et contenu</legend>{view.product.options.length>0?<div className="size-options">{view.product.options.map(option=><button key={option.id} aria-pressed={optionId===option.id} onClick={()=>setOptionId(option.id)} className={optionId===option.id?'chosen':''}><span>{option.label}</span>{!view.product.draftOnly&&<strong>{money(option.price)}</strong>}</button>)}</div>:<p className="source-note">Les dimensions et le contenu de vente sont en cours de confirmation.</p>}</fieldset>
 {view.product.draftOnly?<><button className="button primary full" disabled>Référence en préparation</button><p className="detail-status">Options relevées séparément chez le fournisseur. Associations taille/couleur et stock non confirmés. Prix livré, livraison et conditions de retour à valider avant ouverture.</p></>:<><div className="add-row"><div className="quantity-control"><button aria-label="Diminuer la quantité" disabled={quantity===1} onClick={()=>setQuantity(quantity-1)}><Minus size={15}/></button><span aria-label={`Quantité : ${quantity}`}>{quantity}</span><button aria-label="Augmenter la quantité" disabled={quantity===10} onClick={()=>setQuantity(quantity+1)}><Plus size={15}/></button></div><button className="button primary" disabled={!selectedOption} onClick={()=>addItem(view.product,view.color,optionId,quantity)}>Ajouter au panier <ShoppingBag size={17}/></button></div><p className="detail-status">{shop.checkoutEnabled?`Livraison estimée : ${shop.minDays} à ${shop.maxDays} jours ouvrés. Consultez les conditions de retour.`:'Préouverture · Panier de préparation uniquement. Livraison et conditions de retour à confirmer avant ouverture.'}</p></>}
 <details className="product-specs" open={view.product.draftOnly}><summary>Les détails à connaître <ChevronDown size={16}/></summary><ul>{view.product.details.map(detail=><li key={detail}>{detail}</li>)}</ul></details></div></div></Sheet>}''')
p.write_text(s,encoding='utf8')
print('Storefront updated; cart and checkout logic retained.')
